--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')
local LuaParametersType = LuaParametersReader.Type 
local LuaParametersExpandType = LuaParametersReader.ExpandType


---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Vector4 = CS.UnityEngine.Vector4
local Shader = CS.UnityEngine.Shader


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters



-- ========================================================



local _RolePositionWS = Shader.PropertyToID("_RolePositionWS")

-- ========================================================


function SendRolePosition:__init( onOff_ )
end


function SendRolePosition:__delete()
end




function SendRolePosition:Start()
    KTool.SetActive(self.controller.gameObject, true);

    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    local luaParams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( luaParams )

    self.isActive = LuaParametersReader.Read( luaParams, "isActive", LuaParametersType.Bool )
    self.offset = LuaParametersReader.Read( luaParams, "offset", LuaParametersType.Vector3 ) -- 坐标偏移


    assert(self.targetTransform)
    self.lastFramePosWS = self:GetTargetPos()
end





function SendRolePosition:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function SendRolePosition:Update()

    if self.isActive == false then 
        return
    end

    local pos = self:GetTargetPos()
    if (self.lastFramePosWS - pos).sqrMagnitude > 0.0001 then
        Shader.SetGlobalVector(_RolePositionWS, Vector4(pos.x, pos.y, pos.z, 0))
        self.lastFramePosWS = pos
    end
end




-- =========================================== Self ================================================ --


function SendRolePosition:GetTargetPos()
    return self.targetTransform.position + self.offset
end






return SendRolePosition
